insert into PTL_PORTFOLIO_AUTHORITY (PORTFOLIO_ID, USER_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) select a.* from(
select #{ptlPort.portfolioId,jdbcType=VARCHAR}, #{ptlPort.userId,jdbcType=VARCHAR}, #{ptlPort.createUser,jdbcType=VARCHAR}, #{ptlPort.createDept,jdbcType=VARCHAR}, #{ptlPort.createTime,jdbcType=TIMESTAMP}, #{ptlPort.updateUser,jdbcType=VARCHAR}, #{ptlPort.updateTime,jdbcType=TIMESTAMP} from SYSIBM.SYSDUMMY1
) a
